findings.codeql_raw_query:
/**
 * @name Zip Slip - Arbitrary file write via archive extraction
 * @description Extracting archives without validating file paths can allow writing files outside the target directory
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getACall() and
      source = call.getAMethodCall(["namelist", "infolist", "getinfo"]).getAMethodCall("filename")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("zipfile").getMember("ZipFile").getACall().getAMethodCall(["extract", "extractall"]) or
        call = API::builtin("open").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential zip slip from $@.", source.getNode(), "archive member"
